# Generated by the shell from the palette "{{name}}" ({{mode}}). Edits are overwritten.
# Sourced by ~/.config/zsh/env.zsh and re-sourced by the shells' USR1 reload.
export FZF_DEFAULT_OPTS="
--color=fg:{{fg}},bg:{{bg}},hl:{{purple}}
--color=fg+:{{fgBright}},bg+:{{surface}},hl+:{{cyan}}
--color=info:{{info}},prompt:{{bad}},pointer:{{purple}}
--color=marker:{{good}},spinner:{{purple}},header:{{info}}
--color=border:{{surfaceHi}},label:{{info}},query:{{fgBright}}
--border=rounded
--prompt='🔍 '
--pointer='▶'
--marker='✓'
"
